+  void _attachObligationPendingWaits() {
+    final priorAfter = _agent.afterToolCall;
+    _agent.afterToolCall = (context, cancelToken) async {
+      if (!context.isError && context.toolCall.name == 'schedule_message') {
+        try {
+          await recordPendingWait(
