  const SessionSearchQuery({
    required this.mode,
    required this.scope,
    this.query = '',
    this.kinds = const {},
    this.before,
    this.after,
    this.regex = false,
    this.maxHits = defaultSessionSearchMaxHits,
    this.continuation = 0,
  });

