import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  test('partial census (deadline) does not drop true-branch hits', () async {
    final fs = MemoryFileSystem();
    final repo = JsonlSessionRepo(fs: fs, sessionsRoot: '/sessions');
    final session = await repo.create(
      JsonlSessionCreateOptions(cwd: '/work'),
    );
    // 60 records, EVERY one mentioning the needle (incl. the fork).
    for (var i = 0; i < 60; i++) {
      await session.appendMessage(
        UserMessage.text('needle record number $i'),
      );
    }
    final metadata = await session.getMetadata();

    // A zero-ish budget stops the census almost immediately, mid-prefix.
    final outcome = await searchSessionFile(
      fs,
      metadata.path,
      SessionSearchQuery.fromArgs(const {'query': 'needle'}),
      timeBudget: Duration.zero,
    );
    // The real pass re-reads the chain from the start; even if the
    // deadline also stops it early, hits it DID collect must not be
    // filtered out by a PARTIAL census chain (the true leaf is rec_59).
    print('hits=${outcome.hits.length} examined=${outcome.recordsExamined} '
        'total=${outcome.recordsTotal} reason=${outcome.truncationReason}');
    for (final hit in outcome.hits) {
      print('hit: ${hit.id}');
    }
    // With a healthy budget the same query must return 40 hits (cap).
    final full = await searchSessionFile(
      fs,
      metadata.path,
      SessionSearchQuery.fromArgs(const {'query': 'needle'}),
    );
    print('full hits=${full.hits.length} ids=${full.hits.map((h) => h.id).toList()}');
  });
}
