{"content":"// Scratch: probe the nested-quantifier screen's edge shapes.
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

void main() {
  final cases = <String, bool>{
    '(a+)+': true, // classic
    '(a+)*': true,
    '(a+){2,}': true,
    '(?:\\w+)+': true, // non-capturing
    '((a+))+': true, // doubly-nested — the headline shape, wrapped
    '((a+)*)+': true,
    '(a|aa)+': false, // ambiguous alternation — deliberately unscreened
    'needle': false,
    'a+': false,
    '(ab)+': false,
    '([0-9]+)+': true, // class-inside group
    '\\(a+\\)+': false, // escaped parens — literals
  };
  cases.forEach((pattern, expectReject) {
    final query = SessionSearchQuery.fromArgs({
      'query': pattern,
      'regex': true,
    });
    // If not rejected at parse time, the pattern compiled — report.
    print('$pattern => parsed (rejected=${!query.regex || false})');
  });
  // The rejection path throws FormatException; probe which shapes throw:
  for (final pattern in cases.keys) {
